-- 051. Казахские тексты разборов (/1c), услуг (/uslugi) и кейсов (/keysy).
--
-- ЧЕРНОВОЙ ПЕРЕВОД, сделан ИИ 03.10.2026 — до вычитки носителем языка. Сайт накладывает казахский текст
-- поверх русского по каждому полю (cms.loc), поэтому поле без перевода останется русским, а не пустым.
--
-- Уже внесённые вручную казахские поля не перезаписываются: новое кладётся ПОД существующее
-- (новое || старое — у одинаковых ключей побеждает старое). Повторный запуск ничего не портит.
-- Цифры, цены, сроки и названия программ не менялись. После применения — пересобрать сайт
-- (кнопка публикации в панели или Redeploy в Vercel): страницы собираются заранее.

do $$
declare v_tenant uuid;
begin
  select id into v_tenant from core.tenant where code = 'oberon';
  if v_tenant is null then return; end if;

  -- разборы /1c
  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Құжатты өткізуден бас тарту — көбіне ақау емес, іске қосылған тексеру: бағдарламаға деректер жетпейді немесе минус болмауға тиіс жерде минус шығады. Терезенің төменгі жағындағы қате мәтіні себебін тура атайды, көп жағдайда оны бір минутта-ақ көруге болады.", "steps": ["қате мәтінін толық оқу — онда құжат пен деректеме аталады", "күнді тексеру: кезең жабылып қалмаған ба (Администрирование → Даты запрета)", "қалдықтарды бүгінгі күнге емес, құжат күніне қарау", "толық құқықпен өткізіп көру: өтсе — мәселе құқықтарда", "қате жаңартудан кейін бірден пайда болмағанын тексеру"], "title": "1С-те құжат өткізілмейді", "causes": ["қоймада немесе шотта қалдық жетпейді", "міндетті деректеме толтырылмаған: шарт, шығын бабы, қойма", "құжат күні жабық кезеңге түседі", "пайдаланушының осы түрдегі құжатты өткізуге құқығы жоқ", "өткізу кезінде іске қосылатын жетілдірудегі қате"], "call_us": "Қате мәтіні жетілдіру модулін көрсетсе, құжат барлығында өткізілмесе және бұл жаңартудан кейін басталса немесе тексеру жұмысқа кедергі келтіріп, оны сіздің процесіңізге қарай өзгерту керек болса.", "question": "Құжат неге өткізілмейді және не істеу керек", "symptoms": ["«Өткізу» батырмасын басқанда құжат «өткізілмеген» күйінде қалады", "терезенің төменгі жағында қате мәтіні бар қызыл жол шығады", "бір пайдаланушыда өткізіледі, екіншісінде өткізілмейді"], "seo_title": "1С-те құжат өткізілмейді: себептері және не тексеру керек", "seo_desc": "1С неге құжатты өткізбейтінін талдаймыз: қалдықтар, жабық кезең, құқықтар, жетілдірулер. Өзіңіз не тексере аласыз және қашан бағдарламашы керек."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
         updated_at = now()
   where tenant_id = v_tenant and collection = 'answer' and slug = 'ne-provoditsya-dokument';
  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Банкпен алмасу екі себептің бірінен бұзылады: не файл пішімі өзгерді, не қол жеткізу жоғалды. Екеуін де процестің қай қадамда тоқтайтынына қарап ажыратуға болады — түсіруде, жіберудің өзінде немесе үзіндіні жүктеуде.", "steps": ["түсірілген файлды мәтіндік редактормен ашу: ол бос па, әлде деректері бар ма", "алмасу баптауларын үзінді келетін шотпен салыстыру", "банк-клиенттегі сертификаттың қолданылу мерзімін тексеру", "басқа күнгі үзіндіні жүктеп көру: мәселе бір күнде ме, әлде бүкіл алмасуда ма", "банктен келген хаттарда пішімнің өзгергені туралы хабар бар-жоғын қарау"], "title": "Банкпен алмасу жұмыс істемейді", "causes": ["банк түсіру пішімін немесе файл кодтамасын өзгертті", "сертификаттың мерзімі өтті немесе қол жеткізу кілті ауысты", "1С-те ұйымның немесе шоттың деректемелері өзгерді", "алмасу баптауларында басқа шот немесе басқа қалта көрсетілген", "базадағы контрагентте салыстыру жүргізілетін БСН немесе шот жоқ"], "call_us": "Банк пішімді ауыстырғанда, төлемдерді БСН мен төлем мақсаты бойынша автоматты түрде тарату керек болғанда немесе алмасуды, оның ішінде банкпен тікелей алмасуды, нөлден баптау қажет болғанда.", "question": "Үзінді 1С-ке жүктелмейді, төлем тапсырмалары банкке кетпейді", "symptoms": ["үзінді бос күйде жүктеледі немесе мүлде жүктелмейді", "төлем тапсырмалары түсіріледі, бірақ банк оларды қабылдамайды", "үзіндінің кейбір жолдары контрагентті таппай, оны қолмен көрсетуді сұрайды", "тікелей алмасу (DirectBank) қосылмай қалды"], "seo_title": "Банк үзіндісі 1С-ке жүктелмейді: не істеу керек", "seo_desc": "1С пен банк алмасуы: үзінді неге бос келеді, банк неге төлем тапсырмаларын қабылдамайды, баптаулар мен сертификаттарда не тексеру керек."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
         updated_at = now()
   where tenant_id = v_tenant and collection = 'answer' and slug = 'obmen-s-bankom';
  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "ЭШФ АЖ-ның бас тартуы көбіне 1С-тің өзіне емес, құжат деректеріне қатысты: БСН, өлшем бірлігі, тауардың шығу тегі белгісі немесе жазып беру мерзімі сәйкес келмейді. Бас тарту мәтінін ЭШФ жүйесі жібереді және онда нақты өріс аталады.", "steps": ["бас тарту мәтінін оқу: онда «жалпы қате» емес, нақты өріс аталады", "контрагенттің БСН-ін және оның өзектілігін тексеру", "даулы номенклатура позицияларының өлшем бірліктері мен кодтарын салыстыру", "ЭЦҚ-ның қолданылу мерзімін және кімге берілгенін тексеру", "ұқсас құжатты басқа контрагентке жазып көру"], "title": "ЭШФ жазылмайды немесе қатемен кетеді", "causes": ["контрагенттің БСН/ЖСН-і толтырылмаған немесе қате", "номенклатурада СЭҚ ТН коды немесе шығу тегі белгісі жоқ", "өлшем бірлігі ЭШФ анықтамалығынан алынбаған", "айналым күніне қатысты жазып беру мерзімі бұзылған", "ЭЦҚ сертификатының мерзімі өткен немесе басқа тұлғаға тиесілі"], "call_us": "Бас тартулар топ-тобымен келгенде, кодтар мен белгілерді бір-бірлеп емес, жаппай толтыру керек болғанда немесе ЭШФ сатуды өткізген кезде автоматты түрде жазылуы тиіс болғанда.", "question": "1С-тен электрондық шот-фактура жазғанда қате шығады", "symptoms": ["шот-фактура жіберілгеннен кейін «Қате» мәртебесін алады", "құжат жіберілмей, жобаларда қалып қояды", "жүйе СЭҚ ТН коды немесе өлшем бірлігі қате екенін хабарлайды", "жазып беру мерзімі бойынша қабылданбады"], "seo_title": "ЭШФ 1С-тен жазылмайды: бас тарту себептері, не тексеру керек", "seo_desc": "Қазақстанда 1С-тен электрондық шот-фактура жазудағы қателер: БСН, СЭҚ ТН, өлшем бірліктері, мерзімдер, ЭЦҚ. Өзіңіз не тексере аласыз."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
         updated_at = now()
   where tenant_id = v_tenant and collection = 'answer' and slug = 'esf-oshibka';
  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "1С-тің баяу жұмысы — диагноз емес, белгі ғана. Жабдықты ауыстырмас бұрын барлығында баяулай ма, әлде біреуінде ме, үнемі ме, әлде нақты бір операцияда ма — соны түсіну керек: қайдан іздеу керегі осы жауапқа байланысты, әрі көбіне мәселе компьютерде болмай шығады.", "steps": ["барлығында баяулай ма, әлде біреуінде ме — тексеру", "база файлдық болса, база файлының көлемін қарау", "нақты қай операция ұзаққа созылатынын өлшеу — ашу, өткізу, есеп", "базаны тестілеу және түзету орындалып тұрғанын тексеру", "база қалтасын антивирус тексеруінен шығарып тастау"], "title": "1С баяу жұмыс істейді", "causes": ["файлдық база ұлғайып кеткен және желі арқылы ортақ қалтада тұр", "базаға регламенттік қызмет көрсету орындалмайды", "есептер қажетті кезеңге емес, бүкіл кезеңге құрылады", "жетілдіру циклдің ішінде сұраныс орындайды", "бұғаттаулар: бірнеше адам бір қойма бойынша құжаттарды өткізеді", "антивирус әр жүгінген сайын база файлын тексереді"], "call_us": "Нақты баяу сұранысты табу, базаны клиент-серверлік нұсқаға көшіру немесе қай жетілдіру уақытты жеп жатқанын анықтау керек болғанда. Өлшеу көзбен шамалап емес, журнал бойынша жасалады.", "question": "1С неге баяу жұмыс істейді және оны қалай жылдамдатуға болады", "symptoms": ["құжаттар тізімін ашу ондаған секундқа созылады", "құжатты өткізу бағдарламаны қатырып тастайды", "тек кейбір пайдаланушыларда ғана баяулайды", "кешке қарай таңертеңгіге қарағанда баяуырақ жұмыс істейді"], "seo_title": "1С баяу жұмыс істейді: неге және не істеу керек", "seo_desc": "Баяу 1С: файлдық база, регламенттік операциялар, ауыр есептер, бұғаттаулар және жетілдірулер. Жаңа сервер алмас бұрын себебін қалай анықтауға болады."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
         updated_at = now()
   where tenant_id = v_tenant and collection = 'answer' and slug = '1c-tormozit';
  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Қалдықтардағы алшақтық ешқашан дерлік «кенеттен» пайда болмайды: ол біртіндеп жинақталады. Санды жөндеп қою емес, есеп шынайы жағдайдан алшақтаған күнді табу керек — ары қарай себебі әдетте айқын болады.", "steps": ["қойма бойынша айналым-сальдо ведомосін ай бойынша құрып, алшақтық басталған айды табу", "сол айдың ішінде даулы номенклатура бойынша карточканы қарау", "құжаттар реттілігін тексеру: шығыс кірістен бұрын жүрмей ме", "өткен кезеңдердің құжаттарын кім және қашан түзеткенін қарау", "түзетуден кейін қайта алшақтамас үшін кезеңді жабу"], "title": "Қоймадағы қалдықтар сәйкес келмейді", "causes": ["құжаттар өткен күнмен енгізіледі", "сату кіріс түскенге дейін өткізілген", "атаулары ұқсас номенклатура бойынша сұрып шатасуы (пересорт)", "қозғалыстардың бір бөлігі құжаттарды айналып өтіп, қолмен жүргізіледі", "ай жабылмаған, өзіндік құн есептелмеген"], "call_us": "Алшақтықтар көп болып, оларды қолмен талдау бақылауды баптаудан қымбатқа түскенде: өткен күнмен енгізуге тыйым, өткізу кезінде теріс қалдықтарды тексеру, партиялар бойынша салыстыру.", "question": "Есеп қоймада нақты жатқан саннан басқа санды көрсетеді", "symptoms": ["есепте теріс қалдық тұр", "тауар қоймада бар, ал бағдарламада нөл", "түгендеуден кейін алшақтық бір айдан соң қайта пайда болады", "өзіндік құн себепсіз құбылып тұрады"], "seo_title": "1С-те қалдықтар сәйкес келмейді: себебін қалай табу керек", "seo_desc": "1С-тегі теріс қалдықтар және қоймамен алшақтық: есеп қай айда алшақтағанын қалай табуға болады және қайталанбас үшін не баптау керек."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
         updated_at = now()
   where tenant_id = v_tenant and collection = 'answer' and slug = 'ne-shodyatsya-ostatki';
  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Бұл конфигурация өзгерістерді талдамай жаңартылғанда болады: типтік модульдер жетілдірілген модульдердің үстінен жазылады. Бұл ретте деректер дерлік әрқашан сақталады — жоғалатыны код. Сондықтан алғашқы әрекет «қайта жасау» емес, конфигурацияның бұрынғы нұсқасын қайтарып алу.", "steps": ["базада ары қарай жұмыс істемеу — алдымен ағымдағы күйінің көшірмесін жасау", "жаңартуға дейінгі резервтік көшірмені табу", "бұрынғы конфигурацияны көшірмеден файлға (cf) түсіру", "бұрынғы және ағымдағы конфигурацияларды салыстыру: айырмашылықтар тізімі — жоғалғандардың тізімі", "кеңейтулер бар-жоғын тексеру — олар аман қалуы мүмкін"], "title": "Жаңартудан кейін жетілдірулер өшіп қалды", "causes": ["жаңарту модульдерді толық ауыстырумен орындалған", "жетілдірулер қолдаудан ережеге сай шығарылмай жасалған", "өзгерістер кеңейтуге емес, тікелей типтік модульдерге енгізілген", "жаңарту алдында резервтік көшірме болмаған"], "call_us": "Жетілдірулерді конфигурацияларды салыстыру арқылы жаңа нұсқаға көшіріп, кеңейтулерге шығару үшін — сонда келесі жаңарту оларға тиіспейді. Бұл мәселені біржола шешетін бір реттік жұмыс.", "question": "1С-ті жаңарттық — өз есептеріміз бен түзетулеріміз жұмыс істемей қалды", "symptoms": ["өз есептеріміз бен өңдеулеріміз жоғалып кетті", "баспа нысандары типтік күйіне қайтып келді", "өз деректемелеріміз толтырылмай қалды", "іске қосқанда модульдерде қателер шығады"], "seo_title": "1С жаңартудан кейін жетілдірулер өшті: не істеу керек", "seo_desc": "1С жаңартуы өз есептеріңіз бен баспа нысандарын өшірді: жетілдірулерді резервтік көшірмеден қайтарып, қайталанбас үшін кеңейтулерге қалай шығару керек."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
