  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Айды жабу — бір операция емес, кезек: әрбір келесі операция алдыңғысының нәтижесіне сүйенеді. Сондықтан қате көбіне жабудың өзін емес, оған кедергі болып тұрған құжатты көрсетеді. Талдауды тізімдегі соңғы хабарламадан емес, біріншісінен бастау керек.", "steps": ["тізімдегі соңғы емес, БІРІНШІ қатені оқу: қалғандары әдетте соның салдары", "құжаттар реттілігі қалпына келтірілгенін тексеру", "осы айдағы және алдыңғы айдағы өткізілмеген құжаттарды табу", "бірден керекті айды емес, айларды ретімен жабу", "биыл есеп саясаты өзгерген-өзгермегенін қарау"], "title": "Ай жабылмайды", "causes": ["құжаттар реттілігі бұзылған: шығыс кірістен бұрын тұр", "өткен айлардың құжаттары өткізілмеген", "шығын баптары немесе бөлу тәсілдері толтырылмаған", "осы жылға есеп саясаты бапталмаған", "күні бұрыннан жабық кезеңге түсетін құжаттар бар"], "call_us": "Қате регистрді немесе жетілдіру модулін көрсеткенде, жабу сағаттарға созылғанда немесе шығындар анық бола тұра өзіндік құн нөл болып шыққанда.", "question": "Айды жабу қате береді немесе орындалмайды", "symptoms": ["жабу операциялары қызыл түспен белгіленеді немесе орындалмаған күйде қалады", "жабу өтеді, бірақ өзіндік құн нөлге тең", "жабудан кейін теріс қалдықтар пайда болады", "жабу сағаттап созылады және аяқталмайды"], "seo_title": "1С-те ай жабылмайды: не тексеру керек", "seo_desc": "1С-те айды жабу кезіндегі қателер: құжаттар реттілігі, өткізілмеген құжаттар, шығын баптары, есеп саясаты. Талдауды неден бастау керек."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
