  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Іске қосу кезіндегі хабарлама көбіне себебін атайды, бірақ қорқынышты көрінеді. Кімде іске қосылмайтынын түсіну маңызды: бір адамда ма, әлде барлығында ма. Қайдан іздеу керегі — оның компьютерінде ме, әлде базада ма — осыған байланысты, ал бұл он минут пен тұтас күннің арасындағы айырмашылық.", "steps": ["қате мәтінін толық жазып алу — бұл жауаптың жартысы", "басқаларда іске қосыла ма, тексеру: мәселе компьютерде ме, әлде базада ма", "база қалтасының қолжетімділігін және дискідегі бос орынды тексеру", "белсенді сеанстар тізімін қарап, қатып қалғандарын жабу", "база көшірмесін жасамай тұрып тестілеу мен түзетуді іске ҚОСПАУ"], "title": "1С іске қосылмайды", "causes": ["базасы бар желілік диск қолжетімсіз немесе жол өзгерген", "база зақымданған — әдетте апаттық өшуден кейін", "жабылмаған сессия қалып қойған: база «бос емес»", "платформа жаңарған, ал белгіше (ярлык) ескі нұсқаны көрсетіп тұр", "антивирус база файлын немесе платформаны бұғаттаған", "дискіде орын таусылған"], "call_us": "Егер сөз база зақымдануы туралы болса: кез келген әрекеттің алдында көшірме керек, әйтпесе түзету бүлінген деректердің үстінен жазып жіберуі мүмкін. Сондай-ақ барлығында бірден іске қосылмаса.", "question": "1С-ті іске қосқанда қате шығады немесе бағдарлама ашылмайды", "symptoms": ["ақпараттық база файлы табылмады", "«Ошибка формата потока» (ағын пішімінің қатесі)", "базаны басқа пайдаланушы бұғаттаған", "бағдарлама ашылады да, бірден жабылып қалады", "біреуде іске қосылады, екіншісінде іске қосылмайды"], "seo_title": "1С іске қосылмайды: іске қосу қателері және не істеу керек", "seo_desc": "1С неге іске қосылмайды: база қолжетімсіз, файл зақымданған, сеанс бос емес, платформа ауысқан. Не тексеру керек және неге бірден түзетуді іске қоспау керек."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
