  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "1С-те құжаттар із-түзсіз сирек жоғалады: көбіне олар жоюға белгіленген, тізімде іріктеумен жасырылған немесе басқа кезеңге енгізілген. Шын мәнінде жою да болады, сонда тіркеу журналы көмектеседі — егер ол өшірілмесе, кім, қашан және нені жойғанын сақтап тұрады.", "steps": ["тізімдегі барлық іріктеулерді алып тастап, кезеңді кеңейту", "жоюға белгіленгендерді көрсетуді қосу", "толық мәтінді іздеу арқылы нөмір немесе контрагент бойынша іздеп көру", "тіркеу журналын ашып, «жою» бойынша сүзу", "белгіленген объектілерді жою іске қосылған-қосылмағанын тексеру"], "title": "Құжаттар жоғалып кетті", "causes": ["құжат жоюға белгіленген, сондықтан тізім оны жасырады", "тізімде іріктеу тұр — ұйым, қойма, кезең бойынша", "құжат басқа күнмен енгізіліп, басқа айға «кетіп қалған»", "құжатты пайдаланушы шынымен жойған", "белгіленген объектілерді топтық жою жүргізілген"], "call_us": "Құжаттар қайтарымсыз жойылып, оларды резервтік көшірмеден қалпына келтіру керек болғанда немесе қызметкерлердің бір бөлігіне жою мүмкіндігін жабу қажет болғанда.", "question": "Құжаттар базадан жоғалып кетті немесе оларды біреу жойып жіберді", "symptoms": ["құжат кеше бар еді, бүгін тізімде жоқ", "құжат іздеу арқылы табылады, бірақ журналда көрінбейді", "құжаттағы жолдардың бір бөлігі жоғалып кетті", "есеп сомаларды көрсетеді, бірақ олардың артында құжаттар жоқ"], "seo_title": "1С-те құжаттар жоғалды: қалай табу және қалпына келтіру", "seo_desc": "Құжаттар 1С-тен жоғалып кетті: тізімдегі іріктеулер, жоюға белгі, басқа кезең, шынайы жою. Қалай табуға және кім жойғанын қалай көруге болады."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
