  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Баспа нысаны — ең жиі кездесетін әрі ең қауіпсіз жетілдіру: ол ештеңе есептемейді және есепке әсер етпейді. Маңыздысы — оны қалай жасау. Типтік модульді түзету арқылы енгізілген нысан келесі жаңартуда жоғалады; кеңейтуге шығарылған нысан ешқашан жоғалмайды.", "steps": ["қажетті нысан бұрыннан бар баспа нысандарының арасында жоқ па, тексеру", "нысан жаңартудан кейін жоғалып кетпеді ме, қарау — олай болса, мәселе нысанда емес", "үлгі жинау: нысан қағазда барлық қолтаңбаларымен қалай көрінуі керек", "топтап басып шығару керек пе, шешу — бұл әзірлеу тәсілін өзгертеді"], "title": "Өз баспа нысаныңыз керек", "causes": ["типтік нысанда қажетті өрістер қарастырылмаған", "бұрынғы жетілдіру тікелей типтік модульге енгізілген", "басып шығару басқа макетке бапталған", "құжатта жоқ, байланысты құжаттардан алынатын деректер қажет"], "call_us": "Нысанды типтік модульді түзету арқылы емес, кеңейту ретінде жасау үшін: сонда жаңартулар оған тиіспейді. Әдетте бұл бағасы түсінікті, бірнеше сағаттық жұмыс.", "question": "Баспа нысаны дұрыс емес, үлгіге сай емес немесе мүлде жоқ", "symptoms": ["баспа нысанында қажетті деректемелер немесе қолтаңбалар жоқ", "тапсырыс берушінің немесе банктің үлгісі бойынша бланк керек", "жаңартудан кейін нысан басып шығарылмай қалды", "құжаттарды бір-бірлеп емес, бірден топтап басып шығару керек"], "seo_title": "1С-те өз баспа нысаныңыз: қалай жасау және жоғалтпау", "seo_desc": "1С баспа нысандарын жетілдіру: өз деректемелеріңіз, үлгі бойынша бланк, топтап басып шығару. Нысанды неге типтік модульді түзетіп емес, кеңейтумен жасайды."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
         updated_at = now()
   where tenant_id = v_tenant and collection = 'answer' and slug = 'pechatnaya-forma';
  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "1С-тегі құқықтар рөлдерден, ал рөлдер көптеген ұсақ рұқсаттардан құралады. Сондықтан іс жүзінде «құжатқа қол жеткізу беру» бірден бірнеше рұқсатты білдіреді, ал бір артық рұқсат қосу ойлағаннан көп нәрсені ашып жібереді. Міндеттен бастап талдау керек: адамға неге тыйым салу емес, ол не істеуі ТИІС.", "steps": ["тізім құру: адам не істеуі тиіс, тармақ бойынша", "оның қазір қандай рөлдері мен қол жеткізу топтары бар екенін қарау", "ұйым, қойма және бөлімше бойынша шектеулерді тексеру", "«уақытша» берілген толық құқықтарды алып тастау", "нәтижені өз есептік жазбаңызбен емес, оның есептік жазбасымен тексеру"], "title": "Қызметкер артық нәрсені көреді немесе керегін көрмейді", "causes": ["типтік рөлдер ұйым немесе қойма бойынша шектеусіз толығымен берілген", "жазбалар деңгейіндегі шектеулер бапталмаған", "пайдаланушыда бірнеше рөл бар, құқықтар қосылып кеткен", "толық құқықтар «уақытша» берілген де, солай қалып қойған", "қол жеткізу топтары бапталған, бірақ пайдаланушы оларға қосылмаған"], "call_us": "Жазбалар деңгейінде — ұйым, қойма немесе менеджер бойынша — шектеулер керек болғанда. Бұл бір рет бапталады, бірақ сіздің конфигурацияңызда қол жеткізу топтары қалай құрылғанын түсінуді талап етеді.", "question": "1С-те қол жеткізу құқықтарын баптау", "symptoms": ["менеджер сатып алу бағаларын немесе басқалардың сатылымдарын көреді", "қоймашы құжатты өткізуі тиіс, бірақ өткізе алмайды", "рөл қосқаннан кейін керегінен көп нәрсе ашылып кетті", "қызметкер бір ұйымның орнына барлық ұйымды көреді"], "seo_title": "1С-те қол жеткізу құқықтары: қызметкер артығын көреді", "seo_desc": "1С-те құқықтарды баптау: рөлдер, қол жеткізу топтары, ұйым мен қойма бойынша шектеулер. Бір рөлді қосу неге керегінен көп нәрсені ашады."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
