  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Мұнда екі нәрсені ажырату маңызды: чек басылып шықпады және чек жіберілмеді. Біріншісі бірден көрінеді және әдетте орнында шешіледі; екіншісі мүлде көрінбейді және жинақтала береді — кейін ауысымның жабылмағаны, деректердің берілмегені анықталады.", "steps": ["касса 1С-сіз өзінің қызметтік чегін басып шығара ма, тексеру", "ауысым ашық па және қанша уақыттан бері ашық, қарау", "кассаның интернетпен байланысын тексеру", "1С-тегі жабдықты қосу баптауларын салыстыру", "оператордың кабинетінде құжаттар жетіп жатыр ма, қарау"], "title": "Касса чек шығармайды", "causes": ["касса физикалық түрде ажыратылған немесе қосылу порты ауысқан", "ауысым рұқсат етілгеннен ұзақ ашық тұр және жабуды талап етеді", "фискалдық деректер операторымен байланыс жоқ", "1С-те басқа касса немесе басқа драйвер көрсетілген", "платформа немесе драйвер жаңарып, баптаулар тасталып кеткен"], "call_us": "Чектер басылып шығып, бірақ операторға жетпегенде — бұл үнсіз жинақталады және талдауды қажет етеді. Сондай-ақ жаңа жабдықты баптағанда және басқа кассаға көшкенде.", "question": "Чек басылмайды немесе фискалдық деректер операторына кетпейді", "symptoms": ["төлем кезінде кассалық жабдық қатесі шығады", "чек басылып шығады, бірақ оператордың кабинетінде жоқ", "ауысым жабылмайды", "жаңартудан немесе қайта жүктеуден кейін касса жауап бермей қалды"], "seo_title": "Касса 1С-тен чек шығармайды: не тексеру керек", "seo_desc": "Кассалық жабдық және 1С: төлем кезіндегі қате, чек операторға кетпейді, ауысым жабылмайды. Басып шығару мен беру мәселесін қалай ажыратуға болады."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
