  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Клиент-серверлік нұсқаға көшуді баяу жұмыстың емі ретінде жиі ұсынады, бірақ ол әрдайым ем бола бермейді. Алдымен нақты не баяулайтынын түсіну керек: егер мәселе ауыр есепте немесе жетілдірудің ішіндегі сұраныста болса, сервер көмектеспейді — тек қымбаттай түседі.", "steps": ["нақты қай операция ұзаққа созылатынын өлшеу: ашу, өткізу немесе есеп", "база файлының көлемін және дискідегі бос орынды қарау", "тестілеу және түзету кемінде айына бір рет орындалатынын тексеру", "база қалтасын антивирус тексеруінен шығарып тастау", "барлығында баяулай ма, әлде біреуінде ме — тексеру"], "title": "База ұлғайды: серверге көшетін уақыт келді ме?", "causes": ["файлдық база ортақ қалтада тұр және желі арқылы жұмыс істейді", "регламенттік қызмет көрсету жоқ: база сығылмайды және тексерілмейді", "бірнеше адамның бір құжаттармен бір мезгілде жұмыс істеуі", "бүкіл кезеңге құрылатын ауыр есептер", "жетілдірудің ішіндегі циклдегі сұраныс"], "call_us": "Болжау емес, өлшеу үшін: уақыт қайда кетеді, сервер көмектесе ме және оны ұстау қанша тұрады. Кейде жетілдірудегі бір түзету жеткілікті, ал көшу қажет болмай шығады.", "question": "1С файлдық базасынан клиент-серверлік базаға қашан көшу керек", "symptoms": ["база файлы бірнеше гигабайттан асып кетті", "жұмыс күн соңына қарай баяулайды, қайта іске қосқаннан кейін жылдамдайды", "бірнеше адам бір мезгілде жұмыс істегенде бұғаттаулар басталады", "база тестілеу мен түзетуді барған сайын жиі талап етеді"], "seo_title": "1С файлдық немесе серверлік базасы: қашан көшу керек", "seo_desc": "Клиент-серверлік 1С-ке көшу қашан шынымен қажет, ал қашан мәселе есепте немесе жетілдіруде. Сервер сатып алмас бұрын нені өлшеу керек."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
