  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Штаттағы 1С бағдарламашысына жалақы төлеу керек, ол ауырып та қалады; фрилансерді жарты күн іздейсіз, ал ол сіздің базаңызды есінде сақтамайды. Сүйемелдеу — осы екеуінің ортасы: айына тіркелген сома, кез келген тапсырмаға арналған сағат пакеті және бір сағат ішінде жауап беру уәдесі. Пайдаланылмаған сағаттар күйіп кетпейді, келесі айға ауысады.", "term": "Жұмыс уақытында бір сағат ішінде жауап. Әдеттегі тапсырма — сол күні.", "steps": ["қысқа әңгіме: қандай конфигурациялар, қанша база және пайдаланушы", "базаны аудиттеу: жай-күйін, жаңартулар мен қателерді қараймын — бұл тегін", "сағат пакетін таңдап, шартқа қол қоямыз", "қашықтан қол жеткізуді және резервтік көшіруді баптаймыз", "одан әрі қажет болғанда жай ғана жазасыз"], "title": "1С сүйемелдеу", "result": "Жаңартылған әрі жұмыс істеп тұрған бағдарлама және базаңыздың қандай екенін әр жолы түсіндірмей-ақ жаза алатын адам.", "tagline": "Бағдарламашы бар, оны іздеудің қажеті жоқ", "excluded": ["1С:ИТС жазылымы — ол 1С-тен бөлек сатып алынады және оның өз құны бар", "лицензиялар және бағдарламалардың өзін сатып алу", "бухгалтерлік шешімдер: қанша ҚҚС есептеу керегін бағдарламашы емес, бухгалтер шешеді", "нөлден енгізу және ірі жобалар — бұл өз бағасы бар бөлек жұмыс"], "included": ["айына кез келген тапсырмаға бес сағат жұмыс: жаңартулар, пысықтаулар, қателер, кеңестер", "жұмыс уақытында бір сағат ішінде жауап", "платформа мен конфигурацияны, оның ішінде пысықталғанын да жаңарту", "резервтік көшірмелерді тексеру: олардың жасалып тұрғаны және олардан базаны қалпына келтіруге болатыны", "өтініштер тарихы: әр тапсырма жазылып отырады, жарты жылдан кейін не істелгені және неге екені көрініп тұрады", "ай соңында есеп — қанша сағат жұмсалды және неге"], "seo_desc": "1С абоненттік сүйемелдеуі: айына бес сағат жұмыс, бір сағатта жауап, пысықталған конфигурацияларды жаңарту, резервтік көшірмелерді тексеру. Айына 45 000 ₸-ден.", "seo_title": "Қазақстанда 1С сүйемелдеу: айына 45 000 ₸-ден", "price_note": "Бес сағат үшін айына 45 000 ₸. Он сағат — 85 000 ₸. Пакеттен тыс 10 000 ₸/сағ, пайдаланылмаған сағаттар келесі айға ауысады."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
