  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Типтік конфигурацияны жаңарту жылдар бойы жасалған пысықтауларды өшіріп жібереді. Әдетте бұл кейін белгілі болады: өз есептеріңіз жоғалады, типтік баспа нысандары қайта оралады, өз деректемелеріңіз толтырылмай қалады. Аудит жоғалтулар тізімін алдын ала көрсетеді — конфигурацияның жүктемесі бойынша, жұмыс базаңызға қол жеткізусіз.", "term": "Әдетте екі жұмыс күні. Ірі конфигурациялар — төрт күнге дейін.", "steps": ["конфигурацияны XML файлдарына жүктеп шығарасыз — бұл конфигуратордан жасалады және жұмысты тоқтатуды қажет етпейді", "мұрағатты өзіңізге ыңғайлы кез келген тәсілмен жібересіз", "бүкіл конфигурация бойынша индекс құрып, оны типтікпен салыстырамын", "есепті аласыз және ол бойынша әңгімелесеміз"], "title": "Жаңарту алдындағы жедел аудит", "result": "Пысықтаулар тізімі, жаңарту кезіндегі жоғалтулар тізімі және көшіруді сағатпен бағалау берілген есеп. Құжат сізде қалады және тек менімен емес, кез келген мердігермен сөйлесуге жарайды.", "tagline": "Жаңартқанда не бұзылатынын жаңартуға дейін білу", "excluded": ["конфигурацияны жаңартудың өзі", "пысықтауларды көшіру — бұл аудит қорытындысы бойынша келесі жұмыс", "жұмыс базаңызға қол жеткізу қажет емес және сұралмайды", "базаға өзгеріс енгізілмейді: аудит тек оқиды"], "included": ["конфигурацияңызды сол нұсқадағы типтік конфигурациямен салыстыру", "пысықталған объектілер мен модульдердің толық тізімі", "жаңарту нақты нені өшіретіні, объект бойынша", "нені кеңейтулерге шығарып, енді ешқашан жоғалтпауға болатыны", "көшірудің еңбек сыйымдылығын сағатпен бағалау", "қолдаудан алуды талдау: штаттық жаңартуға не кедергі келтіреді"], "seo_desc": "1С конфигурациясын жаңарту алдында XML-жүктеме бойынша тексеру: пысықтаулар тізімі, жаңарту нені өшіреді, нені кеңейтулерге шығару, көшірудің сағаттық бағасы.", "seo_title": "1С конфигурациясының жаңарту алдындағы аудиті: не бұзылады", "price_note": "Бір конфигурация үшін 45 000 ₸. Сома тіркелген, жұмыс басталғанға дейін белгілі. Кодтың сапасын талдау және пысықтауларды көшіру жоспары керек болса — бұл терең аудит, ол төменде."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
