  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Бес жыл бойы әртүрлі адамдар түзеткен конфигурация — бұл енді «1С» емес, бөтен логикасы бар жеке жүйе. Онда бірдеңе өзгертпес бұрын кім кімді шақыратынын, қай жерде қатені өңдемейтін транзакция бар екенін, қай жерде цикл ішінде сұрау тұрғанын және жаңартудан не бұзылатынын білу керек. Терең аудит бұған жүктеме бойынша, жұмыс базаңызға қол жеткізусіз жауап береді.", "term": "Үш-төрт жұмыс күні. Өте ірі конфигурациялар — бір аптаға дейін.", "steps": ["конфигурацияны конфигуратордан XML файлдарына жүктеп шығарасыз — жұмыс тоқтамайды", "мұрағатты жібересіз; егер онда құпиясөздер мен кілттер болса, бірінші кезекте соны айтамын", "бүкіл конфигурация бойынша индекс құрып, типтікпен салыстырамын", "сапа тексерулерін жүргізіп, шақырулар графын жинаймын", "есепті аласыз және ол бойынша бір сағат әңгімелесеміз"], "title": "Конфигурацияның терең аудиті", "result": "Кез келген мердігерге апаруға болатын құжат: пысықтаулар тізімі, тәуелділіктер картасы, тәуекелдер тізімі және көшіруді сағатпен бағалау. Ол сізде қалады.", "tagline": "Бөтен 1С-ке қол тигізбес бұрын оның ішінде не бар екенін түсіну", "excluded": ["жаңартудың және пысықтауларды көшірудің өзі — бұл келесі жұмыс", "табылғанды түзету: аудит көрсетеді, бірақ жөндемейді", "жұмыс базасына қол жеткізу қажет емес және сұралмайды", "есептің бухгалтерлік сараптамасы — бұл бағдарламашыға емес, аудиторға"], "included": ["сол нұсқадағы типтік конфигурацияға қатысты пысықтаулардың толық тізімі", "шақырулар графы: өзгертілген кодты кім шақырады және түзету нені қозғайды", "сапаны талдау: қатені өңдемейтін транзакциялар, циклдегі сұраулар мен құлыптаулар, динамикалық код, кодта қалып қойған құпиясөздер мен кілттер", "жаңарту нені өшіретіні, объект бойынша", "нені кеңейтулерге шығарып, енді ешқашан жоғалтпауға болатыны", "пысықтауларды көшіруді сағатпен бағалау — жалпы цифрмен емес, әр объект бойынша", "есеп бойынша әңгіме: сұрақтарға бір сағат"], "seo_desc": "Пысықта