  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Алмасулар нашар бапталғандықтан емес, сыртқы жүйелер ескертусіз өзгеретіндіктен бұзылады: банк жүктеме форматын өзгертті, сертификаттың мерзімі өтті, ЭШФ-ке қойылатын талаптар өзгерді. Әдетте бұл туралы жөнелтуі тоқтап қалған қоймашыдан естиді. Бақылау дегеніміз — бұл туралы мен, әрі сізден бұрын білемін деген сөз.", "term": "Бақылауды баптау — бір күннен бастап. Одан әрі бұл жазылым.", "steps": ["қандай алмасуларыңыз бар екенін және олардың қайсысы маңызды екенін қараймыз", "әрқайсысына тексеру баптаймын — ол автоматты түрде орындалады", "хабарламаны тек бірдеңе дұрыс болмағанда ғана аласыз", "айына бір рет — қысқа есеп: не тексерілді, не жөнделді"], "title": "Бақылаудағы алмасулар", "result": "Енді ойлаудың қажеті жоқ алмасулар және жұмыстың тоқтап қалуының орнына ескерту.", "tagline": "Банкпен, ЭШФ-пен және маркетплейстермен алмасу үнсіз тоқтап қалмайды", "excluded": ["алмасуларға қатысы жоқ пысықтаулар — олар бөлек есептеледі", "конфигурацияны жаңарту", "сенімхат қажет болса, сіздің атыңыздан банкке немесе ЭШФ АЖ қолдау қызметіне жүгіну", "жоқ алмасулармен жұмыс: алдымен баптау, содан кейін бақылау"], "included": ["күнделікті тексеру: үзінді жүктелді, төлем тапсырмалары кетті, ЭШФ қабылданды", "бірдеңе өтпей қалса, жұмыста байқалмай тұрып сізге хабарлама", "алмасу жағында бұзылғанды жөндеу", "банкте немесе ЭШФ АЖ-да формат өзгергенде баптауларды түзету", "ай сайын енгізілген жұмыс сағаттары"], "seo_desc": "1С-тің банкпен, ЭШФ АЖ-мен және маркетплейстермен алмасуын күнделікті тексеру. Жөнелту тоқтағанға дейін ақау туралы білесіз. Жұмыс сағаттары енгізілген жазылым.", "seo_title": "1С алмасуларын бақылау: банк, ЭШФ, маркетплейстер", "price_note": "Ай сайын. Бағаға екі сағат жұмыс кіреді; пакеттен тыс 10 000 ₸/сағ. Алмасулар саны бағаға әсер етпейді."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
