  update cms.item set text = jsonb_set(text, '{kz}', $kz${"lead": "Конфигурацияны еріншектіктен емес, қорыққандықтан жаңартпайды: онда пысықтаулар бар, ал олардың қандай екенін енді ешкім есінде сақтамаған. Бір-екі жылдан кейін бұл тұйыққа айналады — заңнама алға кетті, ал жаңарту мүмкін емес. Шешім бір рет жаңартуда емес, пысықтауларды жаңарту енді оларға тимейтін жерге шығаруда.", "term": "Үш күннен бастап. Бес жылдық тарихы бар конфигурация — екі аптаға дейін.", "steps": ["аудит: не пысықталған және жаңарту нені өшіреді", "әр пысықтау бойынша шешеміз — кеңейтуге шығару, қалдыру немесе бас тарту", "базаның көшірмесін жаңартып, соның үстінде тексереміз", "жұмыс базасын жұмыстан тыс уақытта жаңартамыз", "екі апта бақылап, қалған кемшіліктерді жөндейміз"], "title": "Пысықталған конфигурацияны жаңарту", "result": "Өзекті релиз, кеңейтулердегі пысықтаулар және келесі жаңарту жоба емес, кәдімгі жұмыс болатынын түсіну.", "tagline": "Жаңарып, жылдар бойы жасалғанды жоғалтпау", "excluded": ["1С:ИТС жазылымы — онсыз жаңарту жай ғана болмайды", "жаңа пысықтаулар: алдымен жаңартамыз, содан кейін дамытамыз", "пысықтаулар типтік функцияны қайталайтын кездегі жаңарту: алдымен нені қалдыратынымызды шешеміз", "жаңартуға дейін жинақталған есеп қателерін түзету"], "included": ["пысықтауларды кеңейтулерге көшіру — мүмкін болған жерде", "платформа мен конфигурацияны өзекті релизге дейін жаңарту", "жаңартудан кейінгі салыстырып тексеру: баспа нысандары, есептер, алмасулар, құқықтар", "конфигурацияда не қалғаны және неге екенінің тізімі", "тестілік база: алдымен сонда жаңартамыз, содан кейін сізде", "кері қайтару: бірдеңе дұрыс болмаса, бастапқы күйге оралу жоспары"], "seo_desc": "Пысықтауларды кеңейтулерге көшіру, платформа мен конфигурацияны жаңарту, одан кейін тексеру, кері қайтару жоспары. 180 000 ₸-ден, нақты сома аудит бойынша.", "seo_title": "Пысықталған 1С-ті пысықтауларды жоғалтпай жаңарту", "price_note": "180 000 ₸-ден — сағатына 10 000 ₸-ден шамамен он сегіз сағат. Нақты сома