  update cms.item set text = jsonb_set(text, '{kz}', $kz${"who": "Лак-бояу материалдарының саудасы: сатып алушының тапсырысы бойынша бояуға түс беру (колерлеу)", "term": "Тест базасында жиналып, тексерілді, содан кейін жұмыс базасына көшірілді.", "work": ["аппараттың қоспа туралы деректерді қалай беретіні зерттеліп, оның жағында скрипт жазылды", "аралық сервис жасалды: аппарат деректерді соған береді, 1С оларды сол жерден алады — тікелей қосу мүмкін болмады", "қоспаны қабылдап, құжат жасайтын 1С кеңейтімі жазылды", "құжат өздігінен толтырылады: база, колоранттар, мөлшерлер, баға", "шоттар бойынша дұрыс көрсетілуі бапталды — құжат жай ғана жасалып қоймайды, дұрыс өткізіледі", "байланыс үзілген жағдайдағы жұмыс қарастырылды: сервис қолжетімсіз болса да, деректер жоғалмайды"], "title": "1С-те құжаттарды өзі жасайтын колерлеу аппараты", "caveat": "Аппараттың өзіне және оның штаттық бағдарламалық жасақтамасына қол тигізілген жоқ — бұл бөгде техника және бөгде кепілдік. Тарихи бөлігі бөлек әңгіме болып қалды: енгізуге дейін жасалған қоспалар есепке кері күнмен көшірілмеді.", "result": "Колерлеу блокноттағы жазба емес, есеп операциясына айналды. Колоранттардың шығысы нақты қоспа бойынша есептен шығарылады, банканың өзіндік құны есептеледі, қоймадағы қалдықтар сөреде нақты тұрғанмен сәйкес келеді.", "tagline": "Жабдықтағы скрипттен есепте өткізілген құжатқа дейін", "seo_desc": "Жабдықтағы скрипт, аралық сервис, 1С кеңейтімі, құжаттарды автоматты жасау және өткізу, колоранттарды есептен шығару және өзіндік құнды есептеу.", "seo_title": "Кейс: колерлеу аппаратын 1С-пен интеграциялау", "situation": "Колерлеу аппараты өз бетінше, 1С өз бетінше жұмыс істейді. Сатушы банкадағы бояуға түс береді де, кейін есепке қолмен енгізеді: қандай база, қанша колорант кетті, қандай бағамен сатылды. Мұнда қате сирек емес, қалыпты жағдай: ай соңында колоранттар қалдығы сәйкес келмейді, ал банканың өзіндік құны — шамамен алынған шама."}$kz$::jsonb || coalesce(text->'kz', '{}'::jsonb)),
